#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++){ scanf("%d",&p[i]); p[i]--; } // 0-indexed values

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        // x>0, y>0, x+y<n
        ops.push_back({x,y});
        vector<int> np(n);
        // new = suffix(y) + middle(n-x-y) + prefix(x)
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        int m=n-x-y;
        for(int i=0;i<m;i++) np[y+i]=p[x+i];
        for(int i=0;i<x;i++) np[y+m+i]=p[i];
        p=np;
    };

    if(n<=2){
        // n=1: already sorted. n=2: can't do any op (x+y<2, x>=1,y>=1 impossible)
        printf("0\n");
        return 0;
    }

    for(int placed=0; placed<n-1; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: bring element from pos to position 0
        if(pos==0){
            // already at 0
        } else {
            // Use op(1, n-pos): suffix starts at pos, length n-pos
            // Need 1+(n-pos)<n => pos>1
            if(pos>1){
                doOp(1, n-pos);
                // element was at pos, now at position 0
            } else {
                // pos==1. Use op(1,1): suffix=p[n-1], middle=p[1..n-2], prefix=p[0]
                // element at pos=1 goes to middle position 0, which is index 1. Still at 1.
                // Instead: op(2, n-2): suffix=p[2..n-1], middle=empty, prefix=p[0..1]
                // Need 2+(n-2)=n, not <n. Can't.
                // op(1, n-2): suffix=p[2..n-1], middle=p[1], prefix=p[0]
                // element at 1 → middle → index n-2. 
                // Then op(1, 1) to get from n-2... complicated.
                // Just swap using: op(1,1) moves last to front. 
                // First move target to last: op(n-1-1, 1) = op(n-2,1) if pos=1
                // Actually op(1, n-2): new=[p[2]..p[n-1], p[1], p[0]]. Element at 1 goes to n-2.
                doOp(1, n-2); // element goes to position n-2
                doOp(1, 2);   // suffix=p[n-2..n-1] to front. element at n-2 goes to position 0
            }
        }
        // Now element is at position 0, need it at position placed
        if(placed==0) continue;
        // op(placed, n-placed-1): need placed+(n-placed-1)<n => always true since n-1<n
        // new = p[placed+1..n-1] + (empty if middle=0, but n-placed-1+placed=n-1, middle=n-n+1-...wait)
        // middle length = n - placed - (n-placed-1) = 1. middle = p[placed..placed].
        // Hmm. Let me just do: op(1, n-placed-1). suffix=p[placed+1..n-1]→front, middle=p[1..placed], prefix=p[0]→end(pos n-1). Then op(placed,1): suffix=p[n-1]→0, rest shifts. Element ends at 0. 
        // Better: op(n-placed, placed). suffix=p[n-placed..n-1](len placed)→front. prefix=p[0..n-placed-1]→end. Element at 0 → end position n-1... no.
        // op(x,y): element at 0 goes to position y+(n-x-y)+0 .. = n-x. So to put it at placed: n-x=placed => x=n-placed. y can be anything with y>=1, x+y<n => y<placed. So y=1 if placed>1, or need placed>=2.
        if(placed>=2){
            doOp(n-placed, 1);
        } else {
            // placed==1. x=n-1, y>=1, x+y<n => y<1. Impossible.
            // op(1,1): element at 0 → position n-1. Then need from n-1 to 1.
            doOp(1, n-2); // element at 0 → pos n-1... let me compute: n-x=n-1. So element at 0 goes to n-1.
            // Now at n-1. op(1, 1): element at n-1 → suffix → pos 0. Not helpful.
            // op(n-2, 1): element at n-1 → suffix → pos 0. x=n-2,y=1: element at 0→n-x=2. Hmm.
            // Actually let me just use op(1,1): suffix=p[n-1]→0, middle=p[1..n-2], prefix=p[0]→n-1. Element at n-1→0.
            // That undoes it. Instead: op(x,y) where element at n-1 is in suffix when y>=1: it's at n-1, in suffix when y>=1. Goes to position y-1.
            // Want y-1=1 => y=2. x>=1, x+2<n => x<=n-3. 
            doOp(1, 2); // element at n-1 → suffix pos 1. 
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x+0,y+0); // already 1-indexed? No, problem likely 1-indexed values
    // Wait, need to check if values are 1-indexed
    return 0;
}
